import {makeComputedArtifact} from './computed-artifact.js';
import LHTraceProcessor from '../lib/lh-trace-processor.js';

class ProcessedTrace {
  /**
    * @param {LH.Trace} trace
    * @return {Promise<LH.Artifacts.ProcessedTrace>}
